(5799889, 844415, 105441, '<td valign="top">Nice image and cute kid, but I don''t equate it to a father''s love of his daughter.</td>', 'Nice image and cute kid, but I don''t equate it to a father''s love of his daughter.', '2010-01-06 22:52:24.000000', NULL, 1),
(5799890, 844299, 105441, '<td valign="top">Nice concept and execution.  Congrats.</td>', 'Nice concept and execution.  Congrats.', '2010-01-06 22:53:17.000000', NULL, 1),
(5799891, 844289, 70036, '<td valign="top">This is my favorite in the challenge.  It tells a story but I am not sure what.  Excellent use of color without over processing.  Wonderful composition.</td>', 'This is my favorite in the challenge.  It tells a story but I am not sure what.  Excellent use of color without over processing.  Wonderful composition.', '2010-01-06 22:53:29.000000', NULL, 1),
(5799898, 844613, 70036, '<td valign="top">Incredible lighting and/or post processing.  So many interesting places to rest one''s eyes.  There is a lot going on, lighting-wise, in this photo but it all comes together very well as a whole.   Hope you post your post processing in comments.  I assume HDR with lots of dodge and burn.</td>', 'Incredible lighting and/or post processing.  So many interesting places to rest one''s eyes.  There is a lot going on, lighting-wise, in this photo but it all comes together very well as a whole.   Hope you post your post processing in comments.  I assume HDR with lots of dodge and burn.', '2010-01-06 22:57:00.000000', NULL, 1),
(5799944, 843720, 113478, '<td valign="top">Excellent rock, hanging in there, defying gravity &amp; the massive mountain in the background...</td>', 'Excellent rock, hanging in there, defying gravity & the massive mountain in the background...', '2010-01-06 23:58:36.000000', NULL, 1),
(5800319, 844238, 95579, '<td valign="top">Simple &amp; Beautiful</td>', 'Simple & Beautiful', '2010-01-07 10:05:46.000000', NULL, 1),
(5800424, 844106, 113419, '<td valign="top">This is absolutely stunning!  It takes my breath away.  Good Luck!</td>', 'This is absolutely stunning!  It takes my breath away.  Good Luck!', '2010-01-07 11:55:54.000000', NULL, 1),
(5800842, 844300, 100393, '<td valign="top">Magnificent.</td>', 'Magnificent.', '2010-01-07 16:37:41.000000', NULL, 1),
(5800952, 844311, 46918, '<td valign="top">Excellent shot. I have always loved tigers.</td>', 'Excellent shot. I have always loved tigers.', '2010-01-07 18:11:42.000000', NULL, 1),
(5800975, 843811, 22301, '<td valign="top">After seeing so many images on the web, it is much rarer for me to think "wow" but on this I did. I also compliment you for doing it a manner that is irrelevant of it processing. Really cool shot.</td>', 'After seeing so many images on the web, it is much rarer for me to think "wow" but on this I did. I also compliment you for doing it a manner that is irrelevant of it processing. Really cool shot.', '2010-01-07 18:55:47.000000', NULL, 1),
(5801111, 844597, 45672, '<td valign="top">Great shot here!  I like the lighting techniques you used.  I was thinking that a little more DOF would be nice here.  My brain wants to see the entire boot in focus for some reason.  :)<br/> <br/>Very nice shot though!</td>', 'Great shot here!  I like the lighting techniques you used.  I was thinking that a little more DOF would be nice here.  My brain wants to see the entire boot in focus for some reason.  :) Very nice shot though!', '2010-01-07 20:10:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5801113, 844567, 45672, '<td valign="top">Terrific colors and pretty good composition.  I feel like the whites are a little closer to neutral gray than white.  Great depth of field.  All in all, strong image!</td>', 'Terrific colors and pretty good composition.  I feel like the whites are a little closer to neutral gray than white.  Great depth of field.  All in all, strong image!', '2010-01-07 20:11:37.000000', NULL, 1),
(5801119, 844289, 45672, '<td valign="top">Great shot.  This belongs in a National Geo magazine.  Great colors!  Did you try this with a polarizer on?  It may not have worked since the sun was so close to the horizon, but I was just curious.  Great work!</td>', 'Great shot.  This belongs in a National Geo magazine.  Great colors!  Did you try this with a polarizer on?  It may not have worked since the sun was so close to the horizon, but I was just curious.  Great work!', '2010-01-07 20:13:07.000000', NULL, 1),
(5801122, 844298, 45672, '<td valign="top">Very nice lighting!  The cool tones of the lighting really stand out against that backdrop.  Nice execution.</td>', 'Very nice lighting!  The cool tones of the lighting really stand out against that backdrop.  Nice execution.', '2010-01-07 20:13:50.000000', NULL, 1),
(5801124, 843892, 45672, '<td valign="top">Great composition.  I am really impressed.  The dynamic range is really good too.  Congrats on the great image!</td>', 'Great composition.  I am really impressed.  The dynamic range is really good too.  Congrats on the great image!', '2010-01-07 20:14:43.000000', NULL, 1),
(5801126, 844386, 45672, '<td valign="top">Ahh, this is my favorite of the Paul Simon songs.  You did a terrific job lighting this image.  I presume a really high F-stop to get those star effects on the diamonds.  Nicely done!</td>', 'Ahh, this is my favorite of the Paul Simon songs.  You did a terrific job lighting this image.  I presume a really high F-stop to get those star effects on the diamonds.  Nicely done!', '2010-01-07 20:15:57.000000', NULL, 1),
(5801133, 843811, 45672, '<td valign="top">Wow, that''s a hell of a splash.  Nice capture.  What makes this photo for me is the guy in the blue jacket.  It really gives some perspective as to the magnitude of the waves!  My only criticism is that the foreground rocks appear a little over done with some sort of shadow/highlight tool or HDR effect.  Other than that, great work!</td>', 'Wow, that''s a hell of a splash.  Nice capture.  What makes this photo for me is the guy in the blue jacket.  It really gives some perspective as to the magnitude of the waves!  My only criticism is that the foreground rocks appear a little over done with some sort of shadow/highlight tool or HDR effect.  Other than that, great work!', '2010-01-07 20:18:07.000000', NULL, 1),
(5801139, 842934, 45672, '<td valign="top">Terrific lighting!  Cute baby too!</td>', 'Terrific lighting!  Cute baby too!', '2010-01-07 20:20:39.000000', NULL, 1),
(5801142, 843609, 45672, '<td valign="top">This is stunning!  Perfect in all aspects!  Congrats on such a wonderful image.</td>', 'This is stunning!  Perfect in all aspects!  Congrats on such a wonderful image.', '2010-01-07 20:22:04.000000', NULL, 1),
(5801145, 844300, 45672, '<td valign="top">Terrific shot here.  Nice PP of the image.  Superb!</td>', 'Terrific shot here.  Nice PP of the image.  Superb!', '2010-01-07 20:23:06.000000', NULL, 1),
(5801146, 843114, 45672, '<td valign="top">Wow this looks like a postcard.  Nice going!</td>', 'Wow this looks like a postcard.  Nice going!', '2010-01-07 20:23:37.000000', NULL, 1),
(5801152, 843502, 45672, '<td valign="top">I like what you tried to accomplish here.  I think the lighting is just a little harsh for really making this work.  I''m sure you had the right idea in your head.  I think changing the angle of the light source would have helped and possibly softening the light a little bit and maybe even toning it down.  Nice effort.  You were on the right track.  Keep up the practice.  You will nail it soon!</td>', 'I like what you tried to accomplish here.  I think the lighting is just a little harsh for really making this work.  I''m sure you had the right idea in your head.  I think changing the angle of the light source would have helped and possibly softening the light a little bit and maybe even toning it down.  Nice effort.  You were on the right track.  Keep up the practice.  You will nail it soon!', '2010-01-07 20:26:33.000000', NULL, 1),
(5801155, 844299, 45672, '<td valign="top">Terrific image!  Great camera work!</td>', 'Terrific image!  Great camera work!', '2010-01-07 20:27:09.000000', NULL, 1),
(5801562, 842977, 105441, '<td valign="top">Nice portrait, good light, but not a clear connection to a boxer or a clearing.</td>', 'Nice portrait, good light, but not a clear connection to a boxer or a clearing.', '2010-01-07 22:56:03.000000', NULL, 1),
(5801570, 844163, 105441, '<td valign="top">Very nice. To quibble, I think the light from the right is harsh, and leaves a distracting hard shadow below his neck.</td>', 'Very nice. To quibble, I think the light from the right is harsh, and leaves a distracting hard shadow below his neck.', '2010-01-07 22:57:40.000000', NULL, 1),
(5801576, 844344, 42100, '<td valign="top">So unique and wonderful...beautiful textures!</td>', 'So unique and wonderful...beautiful textures!', '2010-01-07 22:58:21.000000', NULL, 1),
(5801592, 843988, 105441, '<td valign="top">My favorite image associated with this lyric!  Great, simple comp.  An 8.</td>', 'My favorite image associated with this lyric!  Great, simple comp.  An 8.', '2010-01-07 23:00:38.000000', NULL, 1),
(5801600, 843793, 105441, '<td valign="top">Nice shot of an emerging icon.</td>', 'Nice shot of an emerging icon.', '2010-01-07 23:03:00.000000', NULL, 1),
(5801607, 844274, 105441, '<td valign="top">A little gray on gray for me, and it would fit better with the lyric is the boat was sailing away from the camera.  And the bridge does not connect with the lyric.</td>', 'A little gray on gray for me, and it would fit better with the lyric is the boat was sailing away from the camera.  And the bridge does not connect with the lyric.', '2010-01-07 23:04:40.000000', NULL, 1),
(5801610, 844259, 105441, '<td valign="top">I have gotta see the photog''s notes on this one!  I like it, but it looks like a graphic rather than a photo, so I hope you explain the processing.</td>', 'I have gotta see the photog''s notes on this one!  I like it, but it looks like a graphic rather than a photo, so I hope you explain the processing.', '2010-01-07 23:05:49.000000', NULL, 1),
(5801611, 844289, 42100, '<td valign="top">I like the foreground inclusion...you did a good job of composing so that it doesn''t compete with the background.  Very nice!</td>', 'I like the foreground inclusion...you did a good job of composing so that it doesn''t compete with the background.  Very nice!', '2010-01-07 23:06:20.000000', NULL, 1),
(5801613, 844325, 105441, '<td valign="top">Picture is OK, but the focal point is a portion of a train in the foreground...</td>', 'Picture is OK, but the focal point is a portion of a train in the foreground...', '2010-01-07 23:06:39.000000', NULL, 1),
(5801618, 842709, 105441, '<td valign="top">Great portrait, caught the eyes very effectively.</td>', 'Great portrait, caught the eyes very effectively.', '2010-01-07 23:07:23.000000', NULL, 1),
(5801632, 842934, 105441, '<td valign="top">Great shot, and I love the simple background.  Well lit, good use of B&amp;W.  A favorite!  8</td>', 'Great shot, and I love the simple background.  Well lit, good use of B&W.  A favorite!  8', '2010-01-07 23:10:22.000000', NULL, 1),
(5801634, 844235, 105441, '<td valign="top">It is hard to see the underlying photo, but this is very creative.</td>', 'It is hard to see the underlying photo, but this is very creative.', '2010-01-07 23:11:29.000000', NULL, 1),
(5801637, 844345, 105441, '<td valign="top">the border ruins it for me.  I like the light in teh branches, though.</td>', 'the border ruins it for me.  I like the light in teh branches, though.', '2010-01-07 23:12:26.000000', NULL, 1),
(5801640, 844416, 105441, '<td valign="top">How did you get the lion to sit so calmly in the studio?  Perfect portrait lighting and composition, so I hope to read the backstory in the photog''s notes!  A 9.</td>', 'How did you get the lion to sit so calmly in the studio?  Perfect portrait lighting and composition, so I hope to read the backstory in the photog''s notes!  A 9.', '2010-01-07 23:15:00.000000', NULL, 1),
(5801646, 844613, 105441, '<td valign="top">Great shot for the lyric, love the sky.  The light on the grass is a little weird, with bright and dark, but overall very good.</td>', 'Great shot for the lyric, love the sky.  The light on the grass is a little weird, with bright and dark, but overall very good.', '2010-01-07 23:15:30.000000', NULL, 1),
(5801647, 844247, 42100, '<td valign="top">Unique and original...great story-telling photo!</td>', 'Unique and original...great story-telling photo!', '2010-01-07 23:15:46.000000', NULL, 1),
(5801667, 842572, 42100, '<td valign="top">Nice crispy detail in this...and lots of good texture.  Very nice!</td>', 'Nice crispy detail in this...and lots of good texture.  Very nice!', '2010-01-07 23:24:13.000000', NULL, 1),
(5801671, 844109, 42100, '<td valign="top">LOL...looks like you and your friends(?) had a lot of fun with this one.  Well done!</td>', 'LOL...looks like you and your friends(?) had a lot of fun with this one.  Well done!', '2010-01-07 23:26:16.000000', NULL, 1),
(5801732, 844300, 42100, '<td valign="top">Nice filtered light...cool photo!  Nice comfy living room you have!  ;)</td>', 'Nice filtered light...cool photo!  Nice comfy living room you have!  ;)', '2010-01-07 23:44:10.000000', NULL, 1),
(5801744, 844410, 42100, '<td valign="top">There are some creative and original photos in this challenge...this is a standout even among those.  Very cool!</td>', 'There are some creative and original photos in this challenge...this is a standout even among those.  Very cool!', '2010-01-07 23:47:12.000000', NULL, 1),
(5801745, 844211, 42100, '<td valign="top">The high contrast is outstanding...works perfectly with this scene!  Great photo!</td>', 'The high contrast is outstanding...works perfectly with this scene!  Great photo!', '2010-01-07 23:47:24.000000', NULL, 1),
(5801746, 844174, 42100, '<td valign="top">You really nailed the tones on this...great portraiture!</td>', 'You really nailed the tones on this...great portraiture!', '2010-01-07 23:47:29.000000', NULL, 1),
(5801747, 844603, 42100, '<td valign="top">What great photo...lots of great things going!  Really like the composition as well!</td>', 'What great photo...lots of great things going!  Really like the composition as well!', '2010-01-07 23:47:36.000000', NULL, 1),
(5801754, 843006, 45672, '<td valign="top">I felt compelled to tell you why you will probably get roughed up a bit on your score in this challenge.  The heron is indeed a little blurry and there is a little noise on the image.  Looking past that, I really like the selection of horizontal lines and compositionally, this photo is pretty good.  Nice work.  I hope it does better than I am guessing.</td>', 'I felt compelled to tell you why you will probably get roughed up a bit on your score in this challenge.  The heron is indeed a little blurry and there is a little noise on the image.  Looking past that, I really like the selection of horizontal lines and compositionally, this photo is pretty good.  Nice work.  I hope it does better than I am guessing.', '2010-01-07 23:57:30.000000', NULL, 1),
(5801757, 844238, 113502, '<td valign="top">Well done.</td>', 'Well done.', '2010-01-07 23:58:32.000000', NULL, 1),
(5801758, 843762, 45672, '<td valign="top">Fantastic capture of these huge waves.  Excellent composition too.  The white balance looks a little off, but all in all, strong image.  Good luck!</td>', 'Fantastic capture of these huge waves.  Excellent composition too.  The white balance looks a little off, but all in all, strong image.  Good luck!', '2010-01-07 23:59:19.000000', NULL, 1),
(5801945, 844163, 49109, '<td valign="top">great lighting here. <strike> Just guessing: <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=20608" rel="nofollow" target="_blank">MAK</a>?</strike> Ok, so obviously not :)</td>', 'great lighting here.  Just guessing:  MAK? Ok, so obviously not :)', '2010-01-08 02:16:30.000000', NULL, 1),
