(5803626, 844174, 93756, '<td valign="top">I like this a lot better than your portrait entry. Great textures in his face.</td>', 'I like this a lot better than your portrait entry. Great textures in his face.', '2010-01-09 10:15:56.000000', NULL, 1),
(5803628, 842053, 93756, '<td valign="top">Oversaturated greens</td>', 'Oversaturated greens', '2010-01-09 10:17:34.000000', NULL, 1),
(5803629, 844610, 93756, '<td valign="top">Funny!</td>', 'Funny!', '2010-01-09 10:17:55.000000', NULL, 1),
(5803635, 843955, 93756, '<td valign="top">This is so close to beautiful but the focus is not on her eyes/face. The sharpest part is her hat. Great color, composition. Love the frame filling hat. Love the snow falling. Her face looks a little too smooth - either overexposed or too much post-smoothing.</td>', 'This is so close to beautiful but the focus is not on her eyes/face. The sharpest part is her hat. Great color, composition. Love the frame filling hat. Love the snow falling. Her face looks a little too smooth - either overexposed or too much post-smoothing.', '2010-01-09 10:23:40.000000', NULL, 1),
(5803644, 843609, 93756, '<td valign="top">Cool scene. To take this to a 10, I think I would have placed the straight ice line to one side instead of sort of down the center of the frame. Crop about 1/4 of the right side of the photo and you have the island at a rule of thirds spot and the line 1/3 of the way into the frame. Would be more dynamic and less just off-center. Love the colors and the wide-angle! Great shot.</td>', 'Cool scene. To take this to a 10, I think I would have placed the straight ice line to one side instead of sort of down the center of the frame. Crop about 1/4 of the right side of the photo and you have the island at a rule of thirds spot and the line 1/3 of the way into the frame. Would be more dynamic and less just off-center. Love the colors and the wide-angle! Great shot.', '2010-01-09 10:29:56.000000', NULL, 1),
(5803646, 844211, 93756, '<td valign="top">Perfect. The small figure just adds to the scale of the scene. I never want to go out to shoot when it''s this kind of weather, but you''ve inspired me that I should!</td>', 'Perfect. The small figure just adds to the scale of the scene. I never want to go out to shoot when it''s this kind of weather, but you''ve inspired me that I should!', '2010-01-09 10:31:23.000000', NULL, 1),
(5803648, 844613, 93756, '<td valign="top">Love the sky!</td>', 'Love the sky!', '2010-01-09 10:31:57.000000', NULL, 1),
(5803649, 842841, 93756, '<td valign="top">Love the post-procesing but the sky is just too electric blue. It doesn''t seem to match the grunginess of the car &amp; barn. Great scene and nicely composed.</td>', 'Love the post-procesing but the sky is just too electric blue. It doesn''t seem to match the grunginess of the car & barn. Great scene and nicely composed.', '2010-01-09 10:33:23.000000', NULL, 1),
(5803651, 844582, 93756, '<td valign="top">Wow, lucky you to be in such a place! I''ll be curious to see where this is. Beautiful shot!</td>', 'Wow, lucky you to be in such a place! I''ll be curious to see where this is. Beautiful shot!', '2010-01-09 10:34:14.000000', NULL, 1),
(5803660, 844598, 93756, '<td valign="top">A tighter crop on the patterns of the coat &amp; umbrella would have made this more dynamic.</td>', 'A tighter crop on the patterns of the coat & umbrella would have made this more dynamic.', '2010-01-09 10:40:55.000000', NULL, 1),
